import"./chunk-2NFLSA4Y.js";var a={induction:{theory:{concept:"[[Electromagnetic induction is the appearance of a voltage (an EMF) in a coil when the magnetic flux through it changes.]] The magnetic flux tells how much magnetic field passes through the coil. Moving a magnet into or out of a coil changes the flux and drives a current around a closed circuit; a magnet that stands still induces nothing, even inside the coil. By Faraday's law, the faster the flux changes, the larger the voltage: \u03B5 = \u2212\u0394\u03A6/\u0394t. The direction of the induced current depends on whether the flux grows or shrinks."},section:{faraday:{title:"Faraday's discovery",text:"In 1831 Michael Faraday found that a magnet can make a current \u2014 but only while something changes. Oersted had shown in 1820 that a current makes a magnetic field; Faraday showed the reverse. This is electromagnetic induction, and almost all the electricity we use is made this way."},change:{title:"Only change counts",text:"Watch the galvanometer. While the magnet moves into the coil, a current flows one way; while it rests inside, there is no current at all; while it moves out, the current flows the other way. Turning the magnet around (south pole first) also reverses the current. A faster movement gives a larger current, but for a shorter time."},flux:{title:"Magnetic flux",text:"[[Magnetic flux \u03A6 measures how much magnetic field passes through the coil: roughly field \xD7 area \xD7 number of turns, \u03A6 = N\xB7B\xB7S.]] It is measured in webers (Wb). Faraday's law says that the induced voltage equals the rate of change of the flux: \u03B5 = \u2212\u0394\u03A6/\u0394t. More turns, a stronger magnet or a faster movement all make the flux change faster."},lenz:{title:"Lenz's law: the coil fights back",text:"[[The minus sign in Faraday's law is Lenz's law: the induced current always opposes the change that causes it.]] While a north pole approaches, the coil's nearest end becomes a north pole too and pushes the magnet away; while the magnet leaves, that end becomes a south pole and pulls it back. The labels on the coil's ends show its induced poles."},energy:{title:"Where the energy comes from",text:"Because the coil always opposes the motion, the hand has to do work to move the magnet. That work becomes the electrical energy that heats the wire (I\xB2\xB7R). Nothing is free: a generator is hard to turn when it powers a lamp. A neat result: the charge that flows during one stroke, Q = |\u0394\u03A6|/R, does not depend on the speed \u2014 a slow push gives a small current for a long time, a fast push a large current for a short time."},everyday:{title:"Induction all around us",text:"Power stations turn huge magnets inside coils (generators). Transformers change voltages for power lines. Induction cookers heat the pot with changing fields, phones charge wirelessly, bicycle dynamos light lamps, and electric cars recover energy when they brake. Card readers and metal detectors work by induction too."},check:{title:"Check your understanding",text:"A magnet rests inside a coil. Is there a current? (No \u2014 the flux does not change.) What changes when you pull the magnet out instead of pushing it in? (The current flows the other way.) How can you get a larger current? (Move faster, use a stronger magnet or more turns.) Why is it harder to push a magnet into a coil connected to a lamp? (The induced current repels the magnet \u2014 Lenz's law.) Try each one in the simulation."}},formula:{faraday:"Faraday's law: induced EMF = rate of change of flux (the minus is Lenz's law)",current:"Induced current in a circuit of resistance R",flux:"Flux through a coil of N turns and area S in a field B",motion:"EMF from a magnet moving at speed v along the axis",charge:"Charge in one stroke: independent of the speed"},variable:{field:"Magnetic field (induction)",area:"Area of one turn"},assumption:{dipole:"The magnet is treated as a small magnetic dipole at its centre; the coil's turns are spread evenly along it.",hand:"The hand moves the magnet at a constant speed (it starts and stops instantly); the coil's self-inductance and the force on the magnet are not simulated.",scale:"Coil: 3 cm radius, 6 cm long. The galvanometer's scale adapts to the experiment; the drawing is not to scale."},param:{motion:"Motion of the magnet",speed:"Speed of the magnet",pole:"Pole facing the coil",turns:"Number of turns in the coil",strength:"Strength of the magnet (magnetic moment, A\xB7m\xB2)",resistance:"Resistance of the circuit",timeStep:"Time step"},hint:{motion:"Push in and pull out, move straight through, or hold the magnet still inside the coil.",speed:"How fast the hand moves the magnet.",pole:"Which end of the magnet points at the coil.",turns:"Every turn of wire adds the same voltage, so more turns give a larger EMF.",strength:"A stronger magnet makes a larger flux and a larger flux change.",resistance:"Coil plus galvanometer. The voltage does not depend on it, the current does: I = \u03B5/R."},preset:{slow:"Slow",normal:"Normal",fast:"Fast"},motion:{inOut:"In, rest, out, rest",through:"Straight through and back",still:"At rest inside the coil"},pole:{north:"North pole (N)",south:"South pole (S)"},measure:{current:"Current now",peakCurrent:"Largest current",velocity:"Velocity of the magnet",emf:"Induced EMF",peakEmf:"Largest EMF",flux:"Magnetic flux through the coil",position:"Position of the magnet",charge:"Charge in this stroke",strokeCharge:"Charge for pushing the magnet in (calculated)"},graph:{emf:"Induced EMF vs time",flux:"Magnetic flux vs time"},view:{north:"N",south:"S",repels:"The coil's near end becomes {pole}: it pushes the magnet away",attracts:"The coil's near end becomes {pole}: it pulls the magnet back",coil:"coil \xB7 {turns} turns",emf:"induced EMF \u03B5 = {emf}",still:"The magnet is not moving: no change, no current",vectorsOption:"Velocity of the magnet",polesOption:"Induced poles and current"},challenge:{still:{title:"A magnet, but no current",description:"Keep the magnet inside the coil without any current.",hint:"Only a change of the magnetic field induces a current."},strong:{title:"Swing the needle",description:"Make the largest current at least 15 mA.",hint:"The faster the flux changes, the larger the current."},gentle:{title:"A gentle push",description:"Move the magnet so that the current never exceeds 1 mA.",hint:"Move it slowly."},reverse:{title:"The other way",description:"Make the current flow the other way while the magnet approaches.",hint:"Turn the magnet around."},bigEmf:{title:"More from the same push",description:"Without moving faster than 0.5 m/s, induce an EMF of at least 200 mV.",hint:"Each turn adds its own voltage, and a stronger magnet gives more flux."},charge:{title:"Move a lot of charge",description:"Make at least 3000 \xB5C flow while the magnet is pushed in.",hint:"Q = |\u0394\u03A6|/R: a larger flux change or a smaller resistance."},slowCharge:{title:"Slow but steady",description:"Pushing in at no more than 0.1 m/s, move at least 1000 \xB5C of charge.",hint:"The charge does not depend on the speed. Change the flux or the resistance instead."}}}},n={sim:a};export{n as default,a as sim};
